const items = $input.all();
if (!items.length) {
  throw new Error("No input received from Extract from File node.");
}

const item = items[0].json;
let rawText = item.text || item.data || item.text_content || item.content || "";

// Convert double quotes to single quotes & sanitize backslashes/newlines
const sanitizedText = String(rawText)
  .replace(/"/g, "'")
  .replace(/\\/g, "/")
  .replace(/[\r\n]+/g, " ")
  .replace(/\s+/g, " ")
  .trim();

return [{
  json: {
    text: sanitizedText
  }
}];

