// Pure JS UUID generator (bypasses n8n crypto restriction)
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const uniqueSopId = generateUUID();

// Safely extract clause_id without crashing if an upstream node hasn't executed
let activeClauseId = 27;
try {
  activeClauseId = $("Module Context").first().json.activeClauseId 
                || $("📦 Module Context").first().json.activeClauseId 
                || $("Webhook Trigger").first().json.body?.clause_id 
                || 27;
} catch (e) {
  activeClauseId = 27;
}

// Read the text response returned by OpenAI
const rawContent = $input.first().json.choices[0].message.content;

// Clean up markdown backticks
const cleanedJsonString = rawContent
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// Parse the JSON output
const parsedData = JSON.parse(cleanedJsonString);

// Safely extract the array whether OpenAI returned [...] or { "sections": [...] }
const sectionsArray = Array.isArray(parsedData) 
  ? parsedData 
  : (parsedData.sections || Object.values(parsedData)[0] || []);

// Return mapped n8n item objects with clause_id and keywords included
return sectionsArray.map((section) => ({
  json: {
    sop_id: uniqueSopId,
    section_number: section.section_number,
    title: section.title,
    content: section.content,
    keywords: Array.isArray(section.keywords) ? section.keywords : [],
    clause_id: activeClauseId
  }
}));

