const responseText = $input.first().json.choices[0].message.content;
const parsedAudit = JSON.parse(responseText);

// Safely extract clause_id without throwing an exception if an upstream node hasn't run
let activeClauseId = 27;
try {
  activeClauseId = $("Webhook Trigger").first().json.body?.clause_id 
                || $("Get Clause Rule").first().json.clause_id 
                || $("Get Clause Rule").first().json.id 
                || 27;
} catch (e) {
  activeClauseId = 27;
}

return [{
  json: {
    score: parsedAudit.score,
    status: parsedAudit.status,
    gaps: parsedAudit.gaps,
    discrepancies: parsedAudit.gaps,
    summary: parsedAudit.summary,
    recommendation: parsedAudit.recommendation || parsedAudit.recommendations || null,
    clause_id: activeClauseId,
    sop_id: $("Save Ingested BPR Sections").first().json.sop_id || null,
    ingestion_id: $("Save Ingested BPR Sections").first().json.id || null
  }
}];

// Combine all reference sections into one formatted string
const sections = $input.all().map(item => item.json);

// Sort by section_number and join text
const fullBenchmarkText = sections
  .sort((a, b) => (a.section_number || 0) - (b.section_number || 0))
  .map(sec => `Section ${sec.section_number || ''}: ${sec.title || 'Untitled'}\n${sec.content || ''}`)
  .join('\n\n');

return [{
  json: {
    golden_sop_text: fullBenchmarkText
  }
}];

return $input.all().map((item, index) => {
  // Access section metadata from the chunking node upstream
  const sectionData = $('Format Sections for Database').all()[index].json;

  return {
    json: {
      sop_id: sectionData.sop_id,
      section_number: sectionData.section_number,
      content: sectionData.content,
      // Pull metadata fields or default if missing
      title: sectionData.title || null,
      clause_id: sectionData.clause_id || null,
      keywords: sectionData.keywords || [],
      embedding: item.json.data[0].embedding
    }
  };
});
